      outline: none;
      box-shadow: 0 0 0 4px rgba(96, 165, 250, 0.22), 0 16px 32px rgba(59, 130, 246, 0.32);
    }

    .form-status {
      min-height: 1.4em;
      margin: 0;
      color: var(--success);
      font-weight: 600;
    }

    @media (max-width: 640px) {
