<body>
  <main class="support-card">
    <p class="eyebrow">Support</p>
    <h1>Contact our team</h1>
    <p class="lead">Send us your details and we will get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field" id="full-name-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jane Doe" required>
        <span class="error-text" id="full-name-error" aria-live="polite"></span>
      </div>

      <div class="form-field" id="email-field">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required>
        <span class="error-text" id="email-error" aria-live="polite"></span>
      </div>

      <div class="form-field" id="phone-field">
        <label for="phone">Phone number</label>
        <input
          id="phone"
          name="phone"
          type="tel"
          autocomplete="tel"
          placeholder="(555) 123-4567"
          aria-describedby="phone-help phone-error"
        >
        <span class="helper-text" id="phone-help">Expected format: +1 555 123 4567 or (555) 123-4567.</span>
        <span class="error-text" id="phone-error" aria-live="polite"></span>
      </div>

      <div class="actions">
        <button type="submit">Send message</button>
      </div>

      <p class="form-status" id="form-status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const status = document.getElementById('form-status');
    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        wrapper: document.getElementById('full-name-field'),
        error: document.getElementById('full-name-error'),
        message: 'Please enter your full name.'
      },
      email: {
        input: document.getElementById('email'),
        wrapper: document.getElementById('email-field'),
        error: document.getElementById('email-error'),
        message: 'Please enter a valid email address.'
      },
      phone: {
        input: document.getElementById('phone'),
        wrapper: document.getElementById('phone-field'),
        error: document.getElementById('phone-error')
      }
    };

    function setFieldState(field, isValid, message = '') {
      field.wrapper.classList.toggle('is-invalid', !isValid);
      field.error.textContent = message;
    }

    function validatePhone(value) {
      if (value.trim() === '') return true;
      const phonePattern = /^(?:\+?\d{1,2}[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}$/;
      return phonePattern.test(value.trim());
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      const fullNameValue = fields.fullName.input.value.trim();
      const emailValue = fields.email.input.value.trim();
      const phoneValue = fields.phone.input.value.trim();

      let isFormValid = true;

      if (!fullNameValue) {
        setFieldState(fields.fullName, false, fields.fullName.message);
        isFormValid = false;
      } else {
        setFieldState(fields.fullName, true);
      }

      if (!fields.email.input.checkValidity()) {
        setFieldState(fields.email, false, fields.email.message);
        isFormValid = false;
      } else {
        setFieldState(fields.email, true);
      }

      if (!validatePhone(phoneValue)) {
        setFieldState(fields.phone, false, 'Enter a phone number like +1 555 123 4567.');
        isFormValid = false;
      } else {
        setFieldState(fields.phone, true);
      }

      if (!isFormValid) return;

      status.textContent = 'Thanks — your message is ready to send.';
      form.reset();
    });

    for (const field of Object.values(fields)) {
      field.input.addEventListener('input', () => {
        if (field === fields.phone) {
          if (field.wrapper.classList.contains('is-invalid') && validatePhone(field.input.value)) {
            setFieldState(field, true);
          }
          return;
        }

        if (field.input.value.trim()) {
          setFieldState(field, true);
        }
